import assert from "node:assert/strict";
import test from "node:test";
import { readFileSync } from "node:fs";
import { IDBFactory } from "fake-indexeddb";
import { bundle } from "./helpers.mjs";

// Generated by the unchanged 0.6.3 source: an unfinished Circuit Lab with a
// prediction, hint, experiment and existing completion. No personal save data.
const legacy = JSON.parse(
  readFileSync(
    new URL("./fixtures/progress-0.6.3.json", import.meta.url),
    "utf8",
  ),
);

test("0.6.3 saves reopen from the existing database without losing lab state or completion", async () => {
  const {
    isProgressState,
    refreshSession,
    modules,
    exercises,
    loadProgress,
    saveProgress,
  } = bundle(`
    export { isProgressState, refreshSession } from './learning/progress';
    export { modules, exercises } from './learning/content';
    export { loadProgress, saveProgress } from './learning/storage';
  `);
  const factory = new IDBFactory();
  const previous = globalThis.indexedDB;
  globalThis.indexedDB = factory;
  try {
    // Insert the old bytes without invoking the new app's save validator.
    await new Promise((resolve, reject) => {
      const request = factory.open("almath-progress", 1);
      request.onupgradeneeded = () =>
        request.result.createObjectStore("progress");
      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        const db = request.result;
        const tx = db.transaction("progress", "readwrite");
        tx.objectStore("progress").put(legacy, "current");
        tx.oncomplete = () => {
          db.close();
          resolve();
        };
        tx.onerror = () => reject(tx.error);
      };
    });
    const loaded = await loadProgress();
    assert.equal(isProgressState(loaded), true);
    assert.deepEqual(loaded, legacy);
    const session = loaded.sessions[loaded.view.sessionKey];
    const module = modules.find((item) => item.id === session.moduleId);
    const refreshed = refreshSession(module, exercises, loaded, session);
    assert.deepEqual(refreshed.drafts, session.drafts);
    assert.equal(refreshed.exerciseIds[refreshed.index], "hw-u2-q28");
    assert.deepEqual(loaded.completed, legacy.completed);
    await saveProgress(loaded);
    assert.deepEqual(await loadProgress(), legacy);
  } finally {
    if (previous === undefined) delete globalThis.indexedDB;
    else globalThis.indexedDB = previous;
  }
});
